using System;
using System.Linq;
using System.Windows;
using System.Windows.Controls;

public partial class Companion {
 Grid workspaceTimerGrid;StackPanel workspaceTimerRight;TextBlock metricTimers,metricTasks,metricMoney;
 void BuildWorkspaceTimers(){
  var p=Stack();p.Children.Add(Text("Напоминания в твоём ритме",13,"Muted"));var metrics=new Grid{Margin=new Thickness(0,9,0,18)};for(int i=0;i<3;i++)metrics.ColumnDefinitions.Add(new ColumnDefinition());
  metricTimers=WorkspaceMetric(metrics,0,"АКТИВНЫХ ТАЙМЕРОВ");metricTasks=WorkspaceMetric(metrics,1,"ЗАДАЧИ НА СЕГОДНЯ");metricMoney=WorkspaceMetric(metrics,2,"БАЛАНС ЗА СЕГОДНЯ");p.Children.Add(metrics);
  workspaceTimerGrid=new Grid();workspaceTimerGrid.SizeChanged+=(s,e)=>UpdateWorkspaceTimerLayout();workspaceTimerGrid.ColumnDefinitions.Add(new ColumnDefinition());workspaceTimerGrid.ColumnDefinitions.Add(new ColumnDefinition());workspaceTimerGrid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});workspaceTimerGrid.RowDefinitions.Add(new RowDefinition{Height=GridLength.Auto});timers=Stack();workspaceTimerGrid.Children.Add(timers);workspaceTimerRight=Stack();Grid.SetColumn(workspaceTimerRight,1);workspaceTimerGrid.Children.Add(workspaceTimerRight);
  var form=Stack();form.Children.Add(Row(DashboardIcon("bell",20),Text("  Новое напоминание",18)));form.Children.Add(Text("Название",11,"Muted"));timerInput=Input("О чём напомнить?");form.Children.Add(timerInput);BuildTimerSchedule(form);
  var presets=new WrapPanel();foreach(int value in new[]{5,30,60}){int preset=value;var button=Btn(value+" мин",()=>{timerHours.Text="0";minutes.Text=preset.ToString();timerDate.Text="";});button.MinWidth=68;button.FontSize=11;presets.Children.Add(button);}form.Children.Add(presets);
  var launch=Btn("+  Создать таймер",()=>Safe(AddTimer),true);launch.MinHeight=43;launch.FontSize=14;launch.Margin=new Thickness(0,9,0,0);launch.HorizontalContentAlignment=HorizontalAlignment.Center;form.Children.Add(launch);timerEditor=Card(form);workspaceTimerRight.Children.Add(timerEditor);
  var quick=Stack();quick.Children.Add(Row(DashboardIcon("clock",20),Text("  Всегда под рукой",16)));quick.Children.Add(Text("Открой таймер в мини-режиме или отдельным виджетом поверх игры.",12,"Muted"));workspaceTimerRight.Children.Add(Card(quick));p.Children.Add(workspaceTimerGrid);Tab("Таймеры",p);
 }
 TextBlock WorkspaceMetric(Grid row,int column,string title){var label=Text(title,9,"Muted");label.Margin=new Thickness(0,0,0,6);var number=Text("0",27,"Accent");var card=NeonMetric(label,number,column==0?"clock":column==1?"check":"coins");card.Margin=new Thickness(0,0,column==2?0:12,0);Grid.SetColumn(card,column);row.Children.Add(card);return number;}
 void UpdateWorkspaceMetrics(){if(metricTimers==null)return;metricTimers.Text=data.Timers.Count(t=>t.End>0&&Left(t)>0).ToString("00");metricTasks.Text=data.Tasks.Count(t=>t.Done)+" / "+data.Tasks.Count;double net=data.Entries.Where(t=>t.Date.Date==DateTime.Today).Sum(t=>t.Income?t.Amount:-t.Amount);metricMoney.Text=(net<0?"- ":"")+Cash(Math.Abs(net));}
 void UpdateWorkspaceTimerLayout(){if(workspaceTimerGrid==null)return;double width=workspaceTimerGrid.ActualWidth>0?workspaceTimerGrid.ActualWidth:workspaceContent==null?Width-80:workspaceContent.ActualWidth;bool wide=width>=720;workspaceTimerGrid.ColumnDefinitions[1].Width=wide?new GridLength(1,GridUnitType.Star):new GridLength(0);Grid.SetColumn(workspaceTimerRight,wide?1:0);Grid.SetRow(workspaceTimerRight,wide?0:1);timers.Margin=new Thickness(0,0,wide?16:0,0);}
 void RenderWorkspaceTimers(){
  if(timers==null)return;timers.Children.Clear();clocks.Clear();toggles.Clear();timerRings.Clear();timerStates.Clear();
  if(data.Timers.Count==0){var empty=Stack();empty.Children.Add(Text("Текущий таймер",14));var circle=new Grid{Width=212,Height=212,Margin=new Thickness(0,25,0,20)};var ring=new CompanionRing{Width=212,Height=212,Progress=.78};Resource(ring,CompanionRing.RingBrushProperty,"RingGradient");Resource(ring,CompanionRing.TrackBrushProperty,"RingTrack");Resource(ring,UIElement.EffectProperty,"NeonRingGlow");circle.Children.Add(ring);var zero=Text("00:00",35,"Muted");zero.TextAlignment=TextAlignment.Center;zero.VerticalAlignment=VerticalAlignment.Center;zero.Margin=new Thickness(0);circle.Children.Add(zero);empty.Children.Add(circle);var label=Text("Пока нет таймеров",15);label.TextAlignment=TextAlignment.Center;empty.Children.Add(label);var hint=Text("Создай напоминание, и оно появится здесь.",12,"Muted");hint.TextAlignment=TextAlignment.Center;empty.Children.Add(hint);timers.Children.Add(Card(empty));}
  foreach(var timer in data.Timers){var content=Stack();var heading=new DockPanel();var state=Text("",10,"Accent");timerStates[timer.Id]=state;DockPanel.SetDock(state,Dock.Right);heading.Children.Add(state);heading.Children.Add(Text("Текущий таймер",13));content.Children.Add(heading);
   var title=Text(timer.Title,19);title.TextAlignment=TextAlignment.Center;title.Margin=new Thickness(0,12,0,8);content.Children.Add(title);var dial=new Grid{Width=212,Height=212,Margin=new Thickness(0,7,0,16)};var ring=new CompanionRing{Width=212,Height=212,Progress=.78};Resource(ring,CompanionRing.RingBrushProperty,"RingGradient");Resource(ring,CompanionRing.TrackBrushProperty,"RingTrack");Resource(ring,UIElement.EffectProperty,"NeonRingGlow");timerRings[timer.Id]=ring;dial.Children.Add(ring);
   var readout=Stack();readout.VerticalAlignment=VerticalAlignment.Center;var clock=Text("",42);clock.Margin=new Thickness(0,0,0,4);clock.TextAlignment=TextAlignment.Center;clocks[timer.Id]=clock;readout.Children.Add(clock);var total=Text("из "+(timer.Duration/60000).ToString("0.#")+" минут",11,"Muted");total.TextAlignment=TextAlignment.Center;readout.Children.Add(total);dial.Children.Add(readout);content.Children.Add(dial);
   var actions=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Center};var toggle=Btn("Пауза",()=>{if(Left(timer)<=0){timer.Remaining=timer.Duration;timer.End=Now+(long)timer.Duration;timer.Alerted=false;}else if(timer.End>0){timer.Remaining=Left(timer);timer.End=0;}else{timer.End=Now+(long)timer.Remaining;timer.Alerted=false;}Save();Tick();},true);toggle.MinWidth=102;toggles[timer.Id]=toggle;actions.Children.Add(toggle);actions.Children.Add(Btn("↶ Заново",()=>{timer.Remaining=timer.Duration;timer.End=Now+(long)timer.Duration;timer.Alerted=false;Save();Tick();}));actions.Children.Add(Btn("×",()=>{data.Timers.Remove(timer);Save();RenderTimers();}));content.Children.Add(actions);var windows=new WrapPanel{HorizontalAlignment=HorizontalAlignment.Center,Margin=new Thickness(0,5,0,0)};windows.Children.Add(PinButton("timer",timer.Id));windows.Children.Add(WidgetButton("timer",timer.Id));content.Children.Add(windows);timers.Children.Add(Card(content));
  }
  Tick();UpdateWorkspaceTimerLayout();
 }
}
